<?php $stages = ['Applied', 'Screening', 'Shortlisted', 'Interview', 'Offer', 'Hired']; ?>
<section class="page-hero"><div class="wrap"><span class="eyebrow">Donums Careers</span><h1>Track your application</h1><p>Enter the reference from your confirmation email and the email address you applied with.</p></div></section>
<section class="section" style="padding-top:34px"><div class="wrap" style="max-width:820px">
  <?php if ($new && $a): ?><div class="flash ok"><?= icon('ok') ?><span><strong>Application received.</strong> Your reference is <strong><?= e($a['ref']) ?></strong>. We have emailed you a confirmation.</span></div><?php endif; ?>
  <form class="card form" method="get" action="/jobs/status"><div class="row2"><div class="field"><label for="ref">Reference</label><input id="ref" name="ref" value="<?= e($ref) ?>" placeholder="APP-261017-A1B2C3" required></div><div class="field"><label for="email">Email address</label><input id="email" type="email" name="email" value="<?= e($email) ?>" required></div></div><div><button class="btn btn-primary">Check status</button></div></form>
  <?php if ($err): ?><div class="flash err mt2"><?= icon('alert') ?><span><?= e($err) ?></span></div><?php endif; ?>
  <?php if ($a): $rej = $a['stage'] === 'Rejected'; $cur = array_search($a['stage'], $stages, true); if ($a['stage'] === 'Assessment') { $cur = 3; } ?>
  <div class="card mt3"><div style="display:flex;justify-content:space-between;gap:12px;flex-wrap:wrap"><div><span class="muted small"><?= e($a['ref']) ?></span><h2 style="margin:0;font-size:1.3rem"><?= e($a['job_title'] ?: 'Talent network') ?></h2><div class="muted"><?= e($a['confidential'] ? 'Confidential employer' : $a['organisation']) ?></div></div><div><?= badge($rej ? 'Not progressed' : $a['stage'], $rej ? 'red' : ($a['stage'] === 'Hired' ? 'green' : 'blue')) ?></div></div>
    <?php if (!$rej && $a['job_id']): ?><div class="grid mt3" style="grid-template-columns:repeat(6,1fr);gap:6px"><?php foreach ($stages as $i => $s): ?><div style="text-align:center"><div style="height:6px;border-radius:99px;background:<?= $i <= (int) $cur ? 'var(--brand)' : '#dfe8e2' ?>"></div><div class="xs mt1" style="font-weight:<?= $i === (int) $cur ? '800' : '500' ?>"><?= e($s) ?></div></div><?php endforeach; ?></div><?php endif; ?>
    <?php if ($interviews): ?><div class="callout info mt3"><strong><?= icon('calendar', 16) ?> Upcoming interview</strong><?php foreach ($interviews as $iv): ?><br><?= e(fmt_dt($iv['starts_at'])) ?> · <?= e($iv['mode']) ?><?= $iv['location'] ? ' · ' . e($iv['location']) : '' ?><?php endforeach; ?></div><?php endif; ?>
    <h3 class="mt3">Progress log</h3><ul class="timeline"><?php foreach (array_reverse($events) as $i => $ev): ?><li class="<?= $i === 0 ? 'cur' : '' ?>"><strong><?= e($ev['to_stage'] ?: 'Update') ?></strong> <span class="muted small">· <?= e(fmt_dt($ev['created_at'])) ?></span><?php if ($ev['note']): ?><br><span class="small"><?= e($ev['note']) ?></span><?php endif; ?></li><?php endforeach; ?></ul>
  </div><?php endif; ?>
</div></section>
